// zz_hud54.js (v0.54) — THE BAR, rebuilt. The user: "I want HUD to look much more improved and refined in detail.
// Closer to the Diablo 2 style but with our own themes applied"; "the orb numbers should be more tastefully designed and
// placed"; "the marrow mana color should be a pearly bone white"; the orbs held by stone ouroboros serpents.
// - The slab is baked pixel art (scratchpad/hud54/hud54.py) at 2 screen px per art px: carved stone, a bronze rail of
//   vertebrae, the experience channel under it, wells for the skills, the belt and the buttons.
// - The glass is painted every frame at 1 screen px per art px: the liquid in flat stepped values (no gradients), a slow
//   swirl in small clusters, a meniscus, a hard window highlight. Each class's resource has its own liquid.
// - The serpents that hold the glass are baked (hud54/serpents.py) and drawn over it.
// - The numbers sit on a small carved plaque above each orb, in the book face.
const HUD54 = { on: true };
{
  const DATA = {"png": "data:image/png;base64,", "layout": {"orbL": {"x": 28, "y": 247, "r": 19}, "orbR": {"x": 452, "y": 247, "r": 19}, "lSkill": 60, "rSkill": 404, "skillY": 249, "gx": 86, "gw": 96, "menuX0": 270, "menuX1": 398, "beltX": 188, "beltY": 250, "wells": [[60, 249, 18, 18], [404, 249, 18, 18], [188, 250, 16, 16], [208, 250, 16, 16], [228, 250, 16, 16], [248, 250, 16, 16], [270, 248, 128, 19]], "gauge": [84, 244, 100, 24], "skulls": [69, 413]}};
  const SERP = {"L": {"png": "data:image/png;base64,", "k": 4, "cx": 144, "cy": 144}, "R": {"png": "data:image/png;base64,", "k": 4, "cx": 144, "cy": 144}};
  const L = DATA.layout, PS = 2;
  const load = src => { const im = new Image(); im.src = src; return im; };
  const panelImg = load(DATA.png);
  let panelLo = null;
  function panelCanvas() {
    if (panelLo || !panelImg.complete || !panelImg.naturalWidth) return panelLo;
    const hr = mkCanvas(panelImg.naturalWidth, panelImg.naturalHeight); hr.getContext('2d').drawImage(panelImg, 0, 0);
    const lo = mkCanvas(hr.width / PS, hr.height / PS); lo.getContext('2d').drawImage(hr, 0, 0, lo.width, lo.height); lo._hr = hr;
    return (panelLo = lo);
  }
  const _hp = hudPanel16;
  hudPanel16 = function () {
    const c = panelCanvas(); if (!c) return _hp.apply(this, arguments);
    ctx.drawImage(c, 0, 222);
  };

  // ---- the serpents (baked frames, one per orb), drawn over the glass
  const serpImgs = {}; for (const k in SERP) serpImgs[k] = { img: load(SERP[k].png), meta: SERP[k], lo: null };
  function serpCanvas(k) {
    const s = serpImgs[k]; if (!s) return null; if (s.lo) return s.lo;
    if (!s.img.complete || !s.img.naturalWidth) return null;
    const K = s.meta.k, hr = mkCanvas(s.img.naturalWidth, s.img.naturalHeight); hr.getContext('2d').drawImage(s.img, 0, 0);
    const lo = mkCanvas(Math.ceil(hr.width / K), Math.ceil(hr.height / K)); lo.getContext('2d').drawImage(hr, 0, 0, lo.width, lo.height); lo._hr = hr;
    return (s.lo = lo);
  }

  // ---- the liquids: six flat steps, dark to light, and a meniscus colour
  const hx = h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
  const LIQ = {
    life:    { p: ['#1a0306', '#3a070c', '#5e0e14', '#86161c', '#ad2a26', '#d2503c'], m: '#e8785a' },
    vitae:   { p: ['#140209', '#2c0610', '#4a0b19', '#6a1324', '#8c1f31', '#b03a46'], m: '#d46070' },
    marrow:  { p: ['#3c3832', '#5e5a50', '#8a8576', '#b3ad9b', '#d6d0bf', '#f1ede1'], m: '#fffaf0', pearl: ['#e6dbe9', '#d5e7e4', '#efe3d2'] },
    essence: { p: ['#060b1a', '#0d1832', '#172c58', '#24457f', '#3764a6', '#6a98d4'], m: '#a8c8f0' },
    miasma:  { p: ['#0e0518', '#1e0b2e', '#321545', '#4a2163', '#673386', '#8e57b4'], m: '#c098e0' },
    empty:   { p: ['#040306', '#08070b', '#0d0c11', '#131218', '#1a1820', '#23212b'] }
  };
  for (const k in LIQ) { LIQ[k].r = LIQ[k].p.map(hx); if (LIQ[k].m) LIQ[k].mr = hx(LIQ[k].m); if (LIQ[k].pearl) LIQ[k].pr = LIQ[k].pearl.map(hx); }
  const GL = {};
  const hash2 = (x, y) => { const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return s - Math.floor(s); };
  // paint one glass: k = fullness 0..1, kind = liquid; K = art px per logical px (4: one screen px each)
  function glass(key, r, k, kind, t, K) {
    K = K || 4; const N = Math.round(2 * r * K);
    let g = GL[key]; if (!g || g.N !== N) { g = GL[key] = { N, hr: mkCanvas(N, N) }; g.x = g.hr.getContext('2d'); g.img = g.x.createImageData(N, N); g.lo = mkCanvas(2 * r, 2 * r); g.lo._hr = g.hr; }
    // v0.75 (perf, user: 'runs really slow on mobile'): the glass was repainted pixel by pixel every frame; now only when its
    // level moves or the surface wave is due (about 12 times a second, 6 on a slow device)
    { const due = window.__perf74 && window.__perf74.slow ? 0.16 : 0.08; if (g.pk != null && g.pkind === kind && Math.abs(g.pk - k) < 0.003 && t - g.pt < due && t >= g.pt) return g.lo; g.pk = k; g.pkind = kind; g.pt = t; }
    const d = g.img.data, Lq = LIQ[kind] || LIQ.life, E = LIQ.empty.r, lvl = 1 - 2 * Math.max(0, Math.min(1, k));
    for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) {
      const o = (j * N + i) * 4, u = (i + 0.5) / N * 2 - 1, v = (j + 0.5) / N * 2 - 1, rr = u * u + v * v;
      if (rr > 1) { d[o + 3] = 0; continue; }
      const cu = Math.floor(i / 2), cv = Math.floor(j / 2);
      const wave = 0.018 * Math.sin(u * 7 + t * 2.3) + 0.01 * Math.sin(u * 13 - t * 1.7);
      let c, idx;
      if (v >= lvl + wave) {
        // the liquid: depth steps, a darker band toward the rim, a slow swirl in small clusters
        idx = 3;
        if (rr > 0.86) idx -= 2; else if (rr > 0.62) idx -= 1;
        const sw = Math.sin(u * 5.2 + v * 3.1 + t * 0.7) + Math.sin(u * -3.3 + v * 6.7 - t * 0.9) + (hash2(cu, cv) - 0.5) * 0.9;
        if (sw > 1.35) idx += 1; else if (sw < -1.5) idx -= 1;
        if (u < -0.15 && v < 0.2 && rr < 0.62 && rr > 0.18) idx += 1;       // the lit side of the liquid, upper left
        if (v < lvl + wave + 0.035) { c = Lq.mr || Lq.r[5]; }                // the meniscus
        else {
          idx = Math.max(0, Math.min(5, idx)); c = Lq.r[idx];
          if (Lq.pr && hash2(cu + Math.floor(t * 2), cv) > 0.965) c = Lq.pr[(cu + cv) % 3];   // pearl flecks in the marrow
        }
        // bubbles rising
        const bx = Math.floor((u + 1) * 6), bph = (t * (0.25 + (bx % 5) * 0.06) + bx * 0.37) % 1, by = 1 - bph * (1 - lvl) * 1.0;
        if (bx % 3 === 0 && Math.abs(v - by) < 0.025 && Math.abs(u - (bx / 6 - 1 + 0.08)) < 0.025) c = Lq.mr || Lq.r[5];
      } else {
        idx = 2; if (rr > 0.8) idx = 1; if (rr > 0.93) idx = 0;
        if (u > 0.25 && u < 0.4 && v < lvl - 0.1) idx = 3;                  // a faint reflection in the empty glass
        c = E[idx];
      }
      // the window highlight: a hard crescent up and left, and a dot
      const ang = Math.atan2(v, u);
      if (rr > 0.5 && rr < 0.66 && ang < -1.9 && ang > -2.75) c = [c[0] * 0.45 + 140, c[1] * 0.45 + 138, c[2] * 0.45 + 132];
      if ((u + 0.36) * (u + 0.36) + (v + 0.44) * (v + 0.44) < 0.006) c = [250, 246, 232];
      d[o] = c[0]; d[o + 1] = c[1]; d[o + 2] = c[2]; d[o + 3] = 255;
    }
    g.x.putImageData(g.img, 0, 0);
    return g.lo;
  }
  HUD54.glass = glass; HUD54.LIQ = LIQ;
  const kindOf = col => ({ '#8e2630': 'life', '#5a1622': 'vitae', '#7a4a1c': 'marrow', '#3a1e50': 'miasma', '#2f5aa8': 'essence' })[col] || 'essence';
  const _orb = drawOrb16;
  drawOrb16 = function (cx, cy, r, v, max, col, dim) {
    if (!HUD54.on) return _orb.apply(this, arguments);
    const kind = kindOf(col), k = max > 0 ? v / max : 0, t = G.time || 0;
    const lo = glass('o' + Math.round(cx), r, k, kind, t);
    ctx.drawImage(lo, Math.round(cx - r), Math.round(cy - r));
    HUD54.serpent(cx, cy, r);
  };
  HUD54.serpent = function (cx, cy, r) {
    const key = cx < W / 2 ? 'L' : 'R', c = serpCanvas(key); if (!c) return;
    const m = serpImgs[key].meta;
    ctx.drawImage(c, Math.round(cx - m.cx / m.k), Math.round(cy - m.cy / m.k));
  };
  // ---- the number on a small carved plaque above the glass
  HUD54.plaque = function (o, s, low) {
    // a bronze-edged plate on the rail, just inside the serpent, toward the middle of the bar
    ctx.save();
    ctx.font = '7px "IM Fell English SC", Georgia, serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    const w = Math.max(16, Math.ceil(ctx.measureText(s).width) + 8), cxp = o.x + (o.x < W / 2 ? 34 : -34);
    const x = Math.round(cxp - w / 2), y = HUD_Y - 13;
    ctx.fillStyle = '#0a090c'; ctx.fillRect(x - 1, y - 1, w + 2, 10);
    ctx.fillStyle = '#4a341b'; ctx.fillRect(x - 0.5, y - 0.5, w + 1, 9);
    ctx.fillStyle = '#7e6034'; ctx.fillRect(x - 0.5, y - 0.5, w + 1, 0.5); ctx.fillRect(x - 0.5, y - 0.5, 0.5, 9);
    ctx.fillStyle = '#1e1a16'; ctx.fillRect(x + 0.5, y + 0.5, w - 1, 7);
    ctx.fillStyle = '#2c2721'; ctx.fillRect(x + 0.5, y + 0.5, w - 1, 0.5);
    for (const px of [x + 1.5, x + w - 2]) { ctx.fillStyle = '#a08450'; ctx.fillRect(px, y + 3.5, 0.5, 0.5); }
    ctx.fillStyle = '#050406'; ctx.fillText(s, cxp + 0.25, y + 6.75);
    ctx.fillStyle = low ? '#f0a890' : '#e6dcc4'; ctx.fillText(s, cxp, y + 6.5);
    ctx.restore();
  };
}
